// ISO 14644-1 cleanroom class from particle counts (>=0.5 um per m^3)
const counts=[3000, 2800, 3100];
const cls=counts.map(c=>c<=3520?5:c<=35200?6:c<=352000?7:c<=3520000?8:9);
console.log('counts:',counts.join(', '));
console.log('ISO classes:',cls.join(', '));

